mapper.select:
/*selectBuyerMpStGiReleaseDirectionsList*/
SELECT CASE WHEN X.STATUS = 1 THEN '출고예정' WHEN X.STATUS = 2 THEN '출고' WHEN X.STATUS = 3 THEN '배송완료' END AS STATUS_TEXT , X.STATUS , X.BUYER , X.RS_NO , X.RS_SEQ , X.RS_REVISION , X.LEGACY_PO_NO , X.GI_NO , X.GI_SEQ , X.DELY_TO_LOCATION , X.DELY_TO_LOCATION_NAME , X.BUYER_ITEM_NO , X.DESCRIPTION , X.SPECIFICATION , X.UNIT_MEASURE , X.ADD_USER_ID , X.REQ_USER_NAME , X.RS_QTY , X.GI_QTY , X.ST_QTY , X.OLD_WBS_NO , X.NEW_WBS_NO , X.RS_DATE , X.GI_DATE , X.DI_DATE FROM ( SELECT CASE WHEN RSDT.COMPLETE_MARK = 'N' THEN 1 WHEN RSDT.COMPLETE_MARK = 'Y' AND GIDT.DI_DATE IS NULL THEN 2 WHEN RSDT.COMPLETE_MARK = 'Y' AND GIDT.DI_DATE IS NOT NULL THEN 3 END AS STATUS , RSDT.BUYER , RSDT.RS_NO , RSDT.RS_SEQ , RSDT.RS_REVISION , RSDT.LEGACY_PO_NO , GIDT.GI_NO , GIDT.GI_SEQ , (SELECT CD2.TEXT1 FROM ICOMCOD2 CD2 WHERE RSDT.DELY_TO_LOCATION = CD2.CODE AND CD2.TYPE = 'C030' AND CD2.COMPANY_CODE = RSDT.BUYER) AS DELY_TO_LOCATION_NAME , RSDT.DELY_TO_LOCATION , RSDT.BUYER_ITEM_NO , (SELECT DESCRIPTION_LOC FROM ICOMBYIT WHERE BUYER = (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = RSDT.BUYER) AND BUYER_ITEM_NO = RSDT.BUYER_ITEM_NO) AS DESCRIPTION , (SELECT SPECIFICATION FROM ICOMBYIT WHERE BUYER = (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = RSDT.BUYER) AND BUYER_ITEM_NO = RSDT.BUYER_ITEM_NO) AS SPECIFICATION , (SELECT UNIT_MEASURE FROM ICOMBYIT WHERE BUYER = (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = RSDT.BUYER) AND BUYER_ITEM_NO = RSDT.BUYER_ITEM_NO) AS UNIT_MEASURE , RSDT.ADD_USER_ID , (SELECT L.USER_NAME_LOC FROM ICOMLUSR L WHERE L.COM_CODE = RSDT.BUYER AND LEGACY_USER_ID = RSDT.ADD_USER_ID) AS REQ_USER_NAME , NVL((SELECT ST.AVAIL_QTY FROM BUYER_STOCK ST WHERE ST.BUYER = RSDT.BUYER AND ST.ITEM_NO = RSDT.BUYER_ITEM_NO),0) AS ST_QTY , NVL(RSDT.RS_QTY,0) AS RS_QTY , NVL(GIDT.GI_QTY,0) AS GI_QTY , RSDT.OLD_WBS_NO , RSDT.NEW_WBS_NO , RSDT.RS_DATE , GIDT.GI_DATE -- 출고일 , GIDT.DI_DATE -- 확정일 FROM BUYER_STOCK_RSDT RSDT , BUYER_STOCK_GIDT GIDT WHERE RSDT.RS_NO = GIDT.RS_NO(+) AND RSDT.RS_SEQ = GIDT.RS_SEQ(+) AND RSDT.RS_REVISION = GIDT.RS_REVISION(+) AND 'D' != GIDT.STATUS(+) AND RSDT.STATUS != 'D' AND RSDT.BUYER = #{st_com_code}
AND RSDT.RS_NO = #{st_rs_no}
AND TO_CHAR(RSDT.ADD_DATE,'YYYYMMDD') >= #{st_from_date}
AND TO_CHAR(RSDT.ADD_DATE,'YYYYMMDD') <= #{st_to_date}
AND RSDT.DELY_TO_LOCATION = #{st_dely_location}
AND RSDT.ADD_USER_ID = #{st_req_user}
) X WHERE X.STATUS = #{st_status} ORDER BY X.RS_NO, X.RS_SEQ, X.STATUS

		/*seletCntForDuplicatedGiRelease*/

		SELECT COUNT(*)
		  FROM BUYER_STOCK_RSDT
		 WHERE BUYER = #{BUYER}
		   AND RS_NO = #{RS_NO}
           AND RS_SEQ = #{RS_SEQ}
           AND RS_REVISION =#{RS_REVISION}
           AND COMPLETE_MARK = 'Y'

		/*seletCheckStockQty*/

		SELECT AVAIL_QTY - #{RS_QTY}
		  FROM BUYER_STOCK
		 WHERE BUYER = #{BUYER}
           AND ITEM_NO = #{BUYER_ITEM_NO}
           AND STATUS = 'C'

		/*seletCheckStockListExists*/

		SELECT COUNT(*)
		  FROM BUYER_STOCK_LIST
		 WHERE BUYER = #{BUYER}
           AND GR_NO = #{GI_NO}
           AND GR_SEQ = #{GI_SEQ}
           AND STATUS != 'D'

		/*seletCheckStockListDeleteExists*/

		SELECT COUNT(*)
		  FROM BUYER_STOCK_LIST
		 WHERE BUYER = #{BUYER}
           AND GR_NO = #{GI_NO}
           AND GR_SEQ = #{GI_SEQ}
           AND STATUS = 'D'

		/*seletCheckStockListDeleteExists*/

		SELECT ITEM_QTY + #{RS_QTY}
		  FROM BUYER_STOCK_LIST
		 WHERE BUYER = #{BUYER}
           AND GR_NO = #{GI_NO}
           AND GR_SEQ = #{GI_SEQ}
           AND STATUS != 'D'

		/*seletCntForDecidedGiRelease*/

		SELECT COUNT(*)
		  FROM BUYER_STOCK_GIDT
		 WHERE GI_NO = #{GI_NO}
		   AND BUYER = #{BUYER}
           AND DI_DATE IS NOT NULL

mapper.update:
/*updateBuyerMpStGidtCancel*/

	UPDATE BUYER_STOCK_GIDT
	  SET STATUS = 'D'
	WHERE BUYER = #{BUYER}
	  AND GI_NO = #{GI_NO}
	  AND GI_SEQ = #{GI_SEQ}
	  AND STATUS != 'D'

/*updateBuyerMpStGiReleaseDirections*/

	UPDATE BUYER_STOCK_RSDT
	  SET COMPLETE_MARK = 'Y'
	WHERE BUYER = #{BUYER}
	  AND RS_NO = #{RS_NO}
	  AND RS_SEQ = #{RS_SEQ}
	  AND RS_REVISION = #{RS_REVISION}
	  AND COMPLETE_MARK != 'Y'
	  AND STATUS != 'D'

/*updateBuyerMpStGiDecideReleaseDirections*/

	UPDATE BUYER_STOCK_GIDT
	  SET DI_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
	    , SND_CHK = 'N'
	    , SND_DATM = NULL
	WHERE BUYER = #{BUYER}
	  AND GI_NO = #{GI_NO}
	  AND STATUS != 'D'

		/*updateBuyerMpStGiDecideIfData*/

			UPDATE IF_SEMES_GI GI
			  SET (GI.GI_COMP_YN, GI.GI_COMP_QTY) = (SELECT 'Y', X.GI_QTY 
                                                 FROM BUYER_STOCK_GIDT X
                                                WHERE X.GI_NO = #{GI_NO}
                                                  AND X.BUYER = #{BUYER}
                                                  AND X.RS_NO = GI.SHIP_COST_ID)
			  WHERE (GI.SHIP_COST_ID, GI.ITEM_CD) IN (SELECT GIDT.RS_NO, RSDT.BUYER_ITEM_NO 
                                                  FROM BUYER_STOCK_GIDT GIDT, BUYER_STOCK_RSDT RSDT
                                                 WHERE GIDT.GI_NO = #{GI_NO}
                                                   AND GIDT.BUYER = #{BUYER}
                                                   AND GIDT.BUYER = RSDT.BUYER
                                                   AND GIDT.RS_NO = RSDT.RS_NO
                                                   AND GIDT.RS_SEQ = RSDT.RS_SEQ
                                                   AND GIDT.RS_REVISION = RSDT.RS_REVISION)
